using System;using System.IO;using System.Collections.Generic;using System.Text;using UnityEditor;using UnityEngine;
namespace MapSharedProps.EditorTools {
public sealed class ChestSurfaceBuilder {
 [Serializable]public class Image {public string png,colorSpace,channels;}
 [Serializable]public class Binding {public string id,assetKey;public int variant;}
 [Serializable]public class OrnamentBinding {public string id,assetKey;public int vertices;public int[] modes;}
 [Serializable]public class Descriptor {public int version,size;public string id;public Image colour,packed;public float[] woodRect,means;public Binding[] assets;public OrnamentBinding[] ornamentsV1;}
 static readonly string[] Ids={"treasurechest_worn","treasurechest","treasurechest_reinforced","treasurechest_ornate","treasurechest_silver","treasurechest_gold","treasurechest_rainbow"};
 readonly Dictionary<string,OrnamentBinding> ornamentBindings=new Dictionary<string,OrnamentBinding>();
 readonly Dictionary<string,Binding> bindings=new Dictionary<string,Binding>();readonly Descriptor data;readonly Texture2D colour,packed;
 static void Check(bool value,string why){if(!value)throw new InvalidDataException("Chest surface: "+why);}
 public static void Validate(SmallPropsV1.Data all){var d=all.chestSurfacesV1;if(d==null||string.IsNullOrEmpty(d.id)&&d.version==0)return;Check(d.version==1&&d.id=="chest-surface-atlas-v1"&&d.size==512&&d.assets!=null&&d.assets.Length>0&&d.assets.Length<=7,"version/count");Check(d.colour!=null&&d.colour.colorSpace=="sRGB"&&d.packed!=null&&d.packed.colorSpace=="linear"&&d.packed.channels=="normalX-normalY-roughness-occlusion","map contract");foreach(var image in new[]{d.colour,d.packed})Check(!string.IsNullOrEmpty(image.png)&&image.png.Length<2000000,"image payload");Check(d.woodRect!=null&&d.woodRect.Length==4&&d.woodRect[0]>=0&&d.woodRect[1]>=0&&d.woodRect[1]<=1&&d.woodRect[2]<=1&&d.woodRect[3]>=0&&d.woodRect[3]<=1&&d.woodRect[2]>d.woodRect[0]&&Math.Abs(d.woodRect[3]-d.woodRect[1])>.00001,"wood UV rectangle");Check(d.means!=null&&d.means.Length==16&&Array.TrueForAll(d.means,v=>!float.IsNaN(v)&&!float.IsInfinity(v)&&v>=0&&v<=1),"far mip means");var seen=new HashSet<string>();foreach(var a in d.assets)Check(a!=null&&a.variant>=0&&a.variant<Ids.Length&&Ids[a.variant]==a.id&&seen.Add(a.id)&&a.assetKey=="tdj/"+a.id&&Array.Exists(all.assets,p=>p.id==a.id&&p.assetKey==a.assetKey),"binding identity");seen.Clear();foreach(var o in d.ornamentsV1??new OrnamentBinding[0]){Check(o!=null&&(o.id==Ids[4]||o.id==Ids[5]||o.id==Ids[6])&&seen.Add(o.id)&&o.assetKey=="tdj/"+o.id&&Array.Exists(d.assets,a=>a.id==o.id),"ornament binding identity");var original=Array.Find(all.chestOrnamentsV1??new ChestPresentationBuilder.Ornament[0],a=>a.id==o.id&&a.assetKey==o.assetKey);Check(original!=null&&original.mesh!=null&&original.mesh.positions!=null&&o.vertices>0&&o.vertices<15000&&o.vertices==original.mesh.positions.Length/3&&o.modes!=null&&o.modes.Length==o.vertices&&Array.TrueForAll(o.modes,v=>v>=0&&v<=3),"ornament mode contract");}}
 static Texture2D Import(Image image){byte[] bytes=Convert.FromBase64String(image.png);string key=SharedAssetFiles.Hash(bytes)+"/"+image.colorSpace+"/bc7-astc6-v1",path=SharedImportCache.Root+"/chest-"+SharedAssetFiles.Hash(Encoding.UTF8.GetBytes(key))+".png";if(!AssetDatabase.IsValidFolder(SharedImportCache.Root))AssetDatabase.CreateFolder("Assets","MapSharedAssetCache");var saved=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(saved)return saved;Check(!File.Exists(path)&&!File.Exists(path+".meta"),"partial image cache");try{File.WriteAllBytes(path,bytes);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Default;importer.sRGBTexture=image.colorSpace=="sRGB";importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=false;importer.mipmapEnabled=true;importer.wrapMode=TextureWrapMode.Clamp;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=2;importer.npotScale=TextureImporterNPOTScale.None;importer.maxTextureSize=512;importer.textureCompression=TextureImporterCompression.CompressedHQ;foreach(string platform in new[]{"Standalone","Android","iPhone"}){var setting=importer.GetPlatformTextureSettings(platform);setting.name=platform;setting.overridden=true;setting.maxTextureSize=512;setting.format=platform=="Standalone"?TextureImporterFormat.BC7:TextureImporterFormat.ASTC_6x6;setting.compressionQuality=75;importer.SetPlatformTextureSettings(setting);}importer.SaveAndReimport();saved=AssetDatabase.LoadAssetAtPath<Texture2D>(path);Check(saved&&saved.width==512&&saved.height==512,"decoded dimensions");return saved;}catch{AssetDatabase.DeleteAsset(path);throw;}}
 public ChestSurfaceBuilder(SmallPropsV1.Data all){data=all.chestSurfacesV1;if(data==null||string.IsNullOrEmpty(data.id))return;Validate(all);foreach(var b in data.assets)bindings.Add(b.id,b);foreach(var o in data.ornamentsV1??new OrnamentBinding[0])ornamentBindings.Add(o.id,o);colour=Import(data.colour);packed=Import(data.packed);}
 public bool HasOrnament(string id){return ornamentBindings.ContainsKey(id);}
 public string OrnamentKey(string id){return HasOrnament(id)?"\n"+JsonUtility.ToJson(ornamentBindings[id]):"";}
 public void ApplyOrnament(Mesh mesh,string id){if(!HasOrnament(id))return;var b=ornamentBindings[id];Check(mesh.vertexCount==b.vertices,"ornament vertex order");var uv=new List<Vector2>(b.vertices);foreach(var mode in b.modes)uv.Add(new Vector2(mode,0));mesh.SetUVs(1,uv);}
 public bool Has(string id){return bindings.ContainsKey(id);}
 public string Key(string id){return Has(id)?"-surface-"+id:"";}
 public Shader ShaderFor(string id,Shader legacy){return Has(id)&&bindings[id].variant<4?Shader.Find("MapSharedProps/ChestWood"):legacy;}
 public void Configure(Material material,string id){if(!Has(id))return;material.EnableKeyword("CHEST_SURFACE");material.SetTexture("_ChestColour",colour);material.SetTexture("_ChestPacked",packed);material.SetFloat("_ChestVariant",bindings[id].variant);var means=new Vector4[4];for(int k=0;k<4;k++)means[k]=new Vector4(data.means[k*4],data.means[k*4+1],data.means[k*4+2],data.means[k*4+3]);for(int k=0;k<4;k++)material.SetVector("_ChestMean"+k,means[k]);material.SetVector("_ChestWoodRect",new Vector4(data.woodRect[0],data.woodRect[1],data.woodRect[2],data.woodRect[3]));}
}
}
